"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi, set_client_factory
from huggingface_hub.utils._http import hf_request_event_hook

logger = logging.getLogger("app.network")

HUB_TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


def _apply_job_settings(request: httpx2.Request) -> None:
    # Many HfApi methods pass `timeout=None` per request, which would disable the
    # client's timeout; enforce ours on every request instead.
    request.extensions = {**request.extensions, "timeout": HUB_TIMEOUT.as_dict()}
    request.headers.update(JOB_HEADERS)


def configure_hub_http(transport=None) -> None:
    def client_factory() -> httpx2.Client:
        # Same setup as huggingface_hub's default client, plus our settings.
        return httpx2.Client(
            event_hooks={"request": [hf_request_event_hook, _apply_job_settings]},
            follow_redirects=True,
            timeout=HUB_TIMEOUT,
            headers=JOB_HEADERS,
            transport=transport,
        )

    # huggingface_hub builds one shared client from this factory, used by all HfApi instances.
    set_client_factory(client_factory)


def current_revision(repo_id: str) -> str | None:
    try:
        return HfApi().model_info(repo_id, revision="main").sha
    except (httpx2.TimeoutException, httpx2.NetworkError) as e:
        logger.warning("Cannot reach the Hugging Face Hub to get the revision of %s: %s", repo_id, e)
        return None

